function UIActionTeamInvitationReceiveDialog:__init() 
    self._data = nil
    self._time = 0
end

function UIActionTeamInvitationReceiveDialog:__delete()
    self._data = nil
    self._time = 0
end

function UIActionTeamInvitationReceiveDialog:Awake()
    SetButtonAction(self.BtnCancel, Bind(self, self.OnBtnCancel))
    SetButtonAction(self.BtnReceive, function()
        if not ActionUtils.CanJump() then return end
        local activityUuid = isNull(self._data.activity) and 0 or checkNumber(self._data.activity.id)
        RegionQuestMgr:GetInstance():FriendRelpyReq({reply = 1, mainPlayerId = self._data.mainData.playerInfo.playerId, activityUuid = activityUuid})
        UIModule.CloseDialog(self.controller)
    end)

    local argument = self.controller.Argument.parameters
    self._data = argument.data
    self._time = argument.time or 30
    self._maxTime = self._time

    self:FillSelf()
    self:StartTimeDown()
end

function UIActionTeamInvitationReceiveDialog:OnBtnCancel()
    local activityUuid = isNull(self._data.activity) and 0 or checkNumber(self._data.activity.id)
    RegionQuestMgr:GetInstance():FriendRelpyReq({reply = 0, mainPlayerId = self._data.mainData.playerInfo.playerId, activityUuid = activityUuid})
    UIModule.CloseDialog(self.controller)
end


function UIActionTeamInvitationReceiveDialog:StartTimeDown()
    if not isNull(self._timeDown) then
        CDTimerModule.GetInstance():RemoveCD(self._timeDown)
        self._timeDown = nil
    end
    self._timeDown = CDTimerModule.GetInstance():AddCD(1, function(count, id)
        self._time = self._time - 1
        CfUtils.FillText(self.TxtTime, self._time)
        self.Fill.fillAmount = (self._maxTime - self._time) / self._maxTime
        if self._time == 0 then
            self:OnBtnCancel()
        end
    end, CountDownTime, false, true)
end

function UIActionTeamInvitationReceiveDialog:FillSelf()
    CfUtils.FillText(self.TxtTime, self._time)
    self.Fill.fillAmount = (self._maxTime - self._time) / self._maxTime

    local info = self._data.mainData.playerInfo
    CfUtils.FillText(self.TxtContent, localize("<color=#ff2dc1>[_name_]</color>邀请您战斗...", {_name_ = info.name}))
    local scr = CfUtils.GetLuaScr(self.CommonPlayerHeadNode, "Game.Behaviours.CommonPlayerHeadNode")
    if scr then
        scr:FreshAvatarFrame(info.avatar, info.avatarFrame)
    end
    
    local questId = self._data.mainData.regionalBossData.questId
    local questVo = QuestConfMgr:GetQuestVoById(questId)
    local difficultLevel = isNull(questVo) and 1 or checkNumber(questVo.label)

    local activityPrefabId = isNull(self._data.activity) and 0 or checkNumber(self._data.activity.prefab)
    local comp = AnnihilationUtils.GetComponent(activityPrefabId)
    local typeId = self._data.mainData.regionalBossData.bossTypeId
    local vo = comp:GetTypeVo(typeId)
    if vo then
        CfUtils.FillImage(self.MonsterInform.transform:Find("ImgFrane/ImgMonster"), vo.overviewBanner)
        CfUtils.FillText(self.TxtName, localize("难度-") .. string.format("%d-%s", difficultLevel, vo.name))
    end
end 


